UPDATE "ec_pages" SET "content" = '[{"_type":"block","_key":"key-2-p4756","style":"normal","children":[{"_type":"span","_key":"key-1-61m13","text":"Jäseneksi tuleminen vaiheissa:"}]},{"_type":"block","_key":"key-5-gg0c6","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-3-kzvrt","text":"Täytä alla oleva lomake ja paina "},{"_type":"span","_key":"key-4-dr6og","text":"Lähetä","marks":["em"]}]},{"_type":"block","_key":"key-7-ln89e","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-6-v5l0j","text":"Jos hallitus hyväksyy sinut jäseneksi, saat ohjeet maksun suorittamiseen"}]},{"_type":"block","_key":"key-12-uox32","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-8-8uaqg","text":"Kun maksu näkyy tilillämme, saat ohjeet Nimenhuudon käyttöön. "},{"_type":"span","_key":"key-10-g7tch","text":"Nimenhuuto-sivustoa","marks":["key-9-s2oho"]},{"_type":"span","_key":"key-11-yutb0","text":" käytetään jäsenten kisailmoittautumiseen."}],"markDefs":[{"_type":"link","_key":"key-9-s2oho","href":"https://hyv.nimenhuuto.com/"}]},{"_type":"block","_key":"key-14-vhoed","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-13-sbcq8","text":"Olet nyt HYV jäsen, hienoa!"}]}]' WHERE id = '01KZ3GA4YR2J3Z9Y2H8J9Y9H89';
