UPDATE "ec_pages" SET "content" = '[{"_type":"block","_key":"key-2-clcyi","style":"normal","children":[{"_type":"span","_key":"key-1-3bc8n","text":"How to become a member step-by-step:"}]},{"_type":"block","_key":"key-4-8j8je","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-3-9029g","text":"Fill in the form and press Send"}]},{"_type":"block","_key":"key-6-3fnec","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-5-5m33b","text":"If the board accepts your application, you will receive instructions for paying the yearly fee (via email)"}]},{"_type":"block","_key":"key-11-1hct9","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-7-a1fwp","text":"When the payment is confirmed, you will receive instructions for using Nimenhuuto (via email). "},{"_type":"span","_key":"key-9-psigx","text":"Nimenhuuto","marks":["key-8-a60ye"]},{"_type":"span","_key":"key-10-94j24","text":" is used for registering to competitions."}],"markDefs":[{"_type":"link","_key":"key-8-a60ye","href":"https://hyv.nimenhuuto.com/"}]},{"_type":"block","_key":"key-13-l03px","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-12-b2ubp","text":"You are now a HYV member, nice!"}]}]' WHERE id = '01KZ3GA7EQZ6EVKYBAQRG9KY9P';
UPDATE "ec_pages" SET "content" = '[{"_type":"block","_key":"key-19-pvn69","style":"normal","children":[{"_type":"span","_key":"key-1-gsbws","text":"Helsingin Yliopiston Voimailijat ry\n","marks":["strong"]},{"_type":"span","_key":"key-2-y6j9j","text":"Founded 17.3.2010 in Helsinki. Our goal is to promote strength training among students.\n\n"},{"_type":"span","_key":"key-3-acsj0","text":"Helsingin Yliopiston Voimailijat ry (HYV) is a member of the Finnish Powerlifting Organization ("},{"_type":"span","_key":"key-5-o2cdl","text":"Suomen Voimanostoliitto SVNL","marks":["key-4-fwbux"]},{"_type":"span","_key":"key-6-s5vma","text":"), the International Powerlifting Federation''s regional affiliate in Finland. Our members can take part in official SVNL competitions (this requires an active license with SVNL and an anti-doping agreement).\n\n"},{"_type":"span","_key":"key-7-x5yaj","text":"First timers can participate in HYV events for free without registration or active membership, otherwise yearly membership fee is 10€. If you decide to come to one of our events as an outsider, please let us know beforehand on "},{"_type":"span","_key":"key-9-b1yrp","text":"Facebook","marks":["key-8-rfnry"]},{"_type":"span","_key":"key-10-x982z","text":", "},{"_type":"span","_key":"key-12-ts3zz","text":"Instagram","marks":["key-11-ly941"]},{"_type":"span","_key":"key-13-s2n47","text":" or by email (using the form at the end of this page).\n"},{"_type":"span","_key":"key-14-fbd4h","text":"NB! Free participation for first timers requires a membership at "},{"_type":"span","_key":"key-16-jy4wz","text":"Unisport","marks":["key-15-a3ki7"]},{"_type":"span","_key":"key-17-5170a","text":" or an otherwise paid entrance fee at the gym the competition is held at.\n\n"}],"markDefs":[{"_type":"link","_key":"key-4-fwbux","href":"https://www.suomenvoimanostoliitto.fi/"},{"_type":"link","_key":"key-8-rfnry","href":"https://www.facebook.com/hyvoimailijat/"},{"_type":"link","_key":"key-11-ly941","href":"https://www.instagram.com/hyvoima/"},{"_type":"link","_key":"key-15-a3ki7","href":"https://unisport.fi/en"},{"_type":"link","_key":"key-18-o7jpw","href":"http://hyvoimailijat.com/Wordpress/wordpress/wp-content/uploads/2019/03/40077704_463121130850215_5454061037978386432_n.png"}]},{"_type":"image","_key":"key-20-pzshq","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQ8VVBY8R0EP9S0A7S21G.png","url":"/_emdash/api/media/file/01KZ3GQ8VVBY8R0EP9S0A7S21G.png"},"alt":""},{"_type":"block","_key":"key-29-p7ajh","style":"normal","children":[{"_type":"span","_key":"key-21-978ss","text":"\n"},{"_type":"span","_key":"key-22-6k651","text":"Contact information\n","marks":["strong"]},{"_type":"span","_key":"key-23-woxvb","text":"Chairman: Jyri Poittinen\n\n"},{"_type":"span","_key":"key-24-xhb8c","text":"Vice chairman: Jaakko Onali\n\n"},{"_type":"span","_key":"key-25-u43a8","text":"Treasurer: Sami Nybom\n\n"},{"_type":"span","_key":"key-26-elor8","text":"Event organizers: Ida Jouhki and Yusif Salam-zade\n\n"},{"_type":"span","_key":"key-27-y3g3j","text":"Secretary: Timo Vuori\n\n"},{"_type":"span","_key":"key-28-ejo87","text":""}]}]' WHERE id = '01KZ3GA8FP1V54ZYVP4XT9BWKF';
