UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-7-ob51v","style":"normal","children":[{"_type":"span","_key":"key-1-sqrfd","text":"New year 2019 started off with the good old bench press: one rep max and maximum reps, both with feet up.\n\n"},{"_type":"span","_key":"key-2-4edtf","text":"Christmas break allowed for plenty of recovery time and so the results proved that as well. This time around HYV oldest veterans did not make it to the event. Everybody had their favorite picked out based on the \"threat levels\". In the rep competition Yusif''s carefree attitude leaving \"a few reps in the tank\" almost backfired. \n\n"},{"_type":"span","_key":"key-3-h8ls6","text":"We let the videos do the speaking, however. In one rep max table we also provide more stats, for example how much competitors would have had to have benched in order to win. \n\n"},{"_type":"span","_key":"key-4-qo505","text":"!NB Due to technical difficulties some of the lifts are missing from the videos, notably first round of 1rm competition and some lifters are missing from the rep competition. \n\n\n"},{"_type":"span","_key":"key-5-jxgs5","text":""}],"markDefs":[{"_type":"link","_key":"key-6-8v440","href":"http://hyvoimailijat.com/Wordpress/wordpress/wp-content/uploads/2019/03/Ryhmäkuva_penkki-1-2019.jpeg"}]},{"_type":"image","_key":"key-8-e6e49","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQ8JN1Y20C9NJA4XTTX2Y.jpeg","url":"/_emdash/api/media/file/01KZ3GQ8JN1Y20C9NJA4XTTX2Y.jpeg"},"alt":""},{"_type":"block","_key":"key-17-q1kww","style":"normal","children":[{"_type":"span","_key":"key-9-y4zrz","text":"From the left: Tuukka, Jaakko, Max, Ville, Jyri, Yusif, Sami, Olaf and Jonne."},{"_type":"span","_key":"key-10-ke7u5","text":"MAX\n","marks":["strong"]},{"_type":"span","_key":"key-11-195im","text":"https://www.youtube.com/watch?v=QmQ8C2nNnLY&feature=youtu.be\n\n"},{"_type":"span","_key":"key-12-rhdch","text":" \n\n"},{"_type":"span","_key":"key-13-mafwh","text":"REPS\n","marks":["strong"]},{"_type":"span","_key":"key-14-czhew","text":"https://www.youtube.com/watch?v=_bUnRKSDH1Q&feature=youtu.be\n\n"},{"_type":"span","_key":"key-15-2agqc","text":"Results:\n","marks":["strong"]}],"markDefs":[{"_type":"link","_key":"key-16-t12cv","href":"http://hyvoimailijat.com/Wordpress/wordpress/wp-content/uploads/2019/03/Tulokset.jpg"}]},{"_type":"image","_key":"key-18-lb6gk","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQ7K8D2FRZ71GBG4ARYTZ.jpg","url":"/_emdash/api/media/file/01KZ3GQ7K8D2FRZ71GBG4ARYTZ.jpg"},"alt":""},{"_type":"block","_key":"key-22-s761n","style":"normal","children":[{"_type":"span","_key":"key-19-jvno2","text":"\n"},{"_type":"span","_key":"key-20-3nucu","text":"Voimaliiga points:\n","marks":["strong"]}],"markDefs":[{"_type":"link","_key":"key-21-pk6ii","href":"http://hyvoimailijat.com/Wordpress/wordpress/wp-content/uploads/2019/03/Pistetilanne_Miehet.jpg"}]},{"_type":"image","_key":"key-23-ryysg","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQ88J9F07C14QF443TJDP.jpg","url":"/_emdash/api/media/file/01KZ3GQ88J9F07C14QF443TJDP.jpg"},"alt":""},{"_type":"block","_key":"key-29-h1g26","style":"normal","children":[{"_type":"span","_key":"key-24-q7upi","text":"\n"},{"_type":"span","_key":"key-25-baw8e","text":" \n\n"},{"_type":"span","_key":"key-26-qopwv","text":"Translated by: Yusif\n\n"},{"_type":"span","_key":"key-27-7n9qn","text":"Original text: Jaakko\n\n"},{"_type":"span","_key":"key-28-4za1e","text":"Videos: Tuukka"}]}]' WHERE id = '01KZ3GDXEATBC521HFR6A687WC';
UPDATE "ec_posts" SET "content" = '[{"_type":"image","_key":"key-4-05zak","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQA45YSJ55XSHYEHADJ78.jpg","url":"/_emdash/api/media/file/01KZ3GQA45YSJ55XSHYEHADJ78.jpg"},"alt":""},{"_type":"block","_key":"key-13-hvsqq","style":"normal","children":[{"_type":"span","_key":"key-5-9u1zw","text":"Vasemmalta ylhäältä: Jaakko, Olaf, Tommi, Sonja, Valtteri, Max, Ville, Pasi. Alhaalla Yusif ja Sami."},{"_type":"span","_key":"key-6-36kjl","text":"Jotta tuntuma maastavetoon ei pääsisi puolen vuoden aikana katoamaan, on HYV:n voimaliigan osakilpailuksi vakiintunut Push&Pull-kisa, jossa lajeina on penkkipunnerrus ja maastanosto - molemmat voimanostosäännöin.\n\n"},{"_type":"span","_key":"key-7-rb5oq","text":"Osanottajia oli tällä kertaa 8 (7 miestä ja 1 nainen), joista kaikki olivat vanhoja kisaajia edellisistä mittelöistä.\n\n"},{"_type":"span","_key":"key-8-hexpb","text":"Mainittavia suorituksia oli Olafin 160 kilon penkki ja Yusifin 99 % RAW (no belt, sumo) 245 kilon maastanosto. Videolta voit katsoa onnistuivatko nämä nostot ;)\n\n"},{"_type":"span","_key":"key-9-wnr1w","text":"https://www.youtube.com/watch?v=hVWmCUIB_NI\n\n"},{"_type":"span","_key":"key-10-60trj","text":" \n\n"},{"_type":"span","_key":"key-11-ubi8t","text":"TULOKSET:","marks":["strong"]}],"markDefs":[{"_type":"link","_key":"key-12-z6rzw","href":"http://hyvoimailijat.com/Wordpress/wordpress/wp-content/uploads/2019/05/Tulokset_PushPull-3-2019.jpg"}]},{"_type":"image","_key":"key-14-dsnp3","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQ9554XENM1FKBPDQQHHJ.jpg","url":"/_emdash/api/media/file/01KZ3GQ9554XENM1FKBPDQQHHJ.jpg"},"alt":""},{"_type":"block","_key":"key-19-s0ygx","style":"normal","children":[{"_type":"span","_key":"key-15-qtyn7","text":"\n"},{"_type":"span","_key":"key-16-smakk","text":"PISTETILANNE\n","marks":["strong"]},{"_type":"span","_key":"key-17-718xy","text":"Miehet\n\n"}],"markDefs":[{"_type":"link","_key":"key-18-6709f","href":"http://hyvoimailijat.com/Wordpress/wordpress/wp-content/uploads/2019/05/PISTETILANNE_miehet.jpg"}]},{"_type":"image","_key":"key-20-rovae","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQ9ECE7C24KKHNBAK7AZ8.jpg","url":"/_emdash/api/media/file/01KZ3GQ9ECE7C24KKHNBAK7AZ8.jpg"},"alt":""},{"_type":"block","_key":"key-24-j96u4","style":"normal","children":[{"_type":"span","_key":"key-21-isi8v","text":"\n"},{"_type":"span","_key":"key-22-leznl","text":"Naiset:\n\n"}],"markDefs":[{"_type":"link","_key":"key-23-2cu8h","href":"http://hyvoimailijat.com/Wordpress/wordpress/wp-content/uploads/2019/05/PISTETILANNE_naiset.jpg"}]},{"_type":"image","_key":"key-25-3oy85","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQ9QQ0H2DYZ7573XMFXX2.jpg","url":"/_emdash/api/media/file/01KZ3GQ9QQ0H2DYZ7573XMFXX2.jpg"},"alt":""},{"_type":"block","_key":"key-29-9ntp5","style":"normal","children":[{"_type":"span","_key":"key-26-3h6hy","text":"\n"},{"_type":"span","_key":"key-27-3305y","text":"Teksti: Jaakko\n\n"},{"_type":"span","_key":"key-28-vqpc9","text":"Video: Yusif"}]}]' WHERE id = '01KZ3GDYCZKGE8BC27JN3P0ZHA';
UPDATE "ec_posts" SET "content" = '[{"_type":"image","_key":"key-4-9ezhy","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQB5SWVB0WFJQ1MYF6TEB.jpg","url":"/_emdash/api/media/file/01KZ3GQB5SWVB0WFJQ1MYF6TEB.jpg"},"alt":""},{"_type":"block","_key":"key-14-xqrm7","style":"normal","children":[{"_type":"span","_key":"key-5-y41hh","text":"Vasemmalta: Simo, Yusif, Leo, Eero ja Jaakko"},{"_type":"span","_key":"key-6-eepm3","text":"Otsikko on hiukan harhaanjohtava, sillä selän mittaaminen ei vielä kuulu voimaliigan osakilpailuihin. Jotain sen suuntaista kisaa on kuitenkin mietitty järjestettävän... ;)\n\n"},{"_type":"span","_key":"key-7-jo7hz","text":"Aiheeseen: huhtkuussa käytiin kauden 2018 - 2019 toiseksi viimeinen osakilpailu. Lajina leuanveto (ykkös- ja toistomaksimi) ja paikkana Meilahden Unisport.\n\n"},{"_type":"span","_key":"key-8-lexek","text":"Kuten HYV:ssä on tapana, oli uhoamista havaittavissa tovin aikaa ennen kisaa. Taktikointia nähtiin myös ja voittoon ylsikin tällä kertaa maksimikisassa debytoinut Simo ja toistokisassa jo neljättä vuotta putkeen Jaakko. Taso oli kova, mutta valitettavasti viime vuoden kovimmista nostajista moni ei päässyt tulemaan paikalle.\n\n"},{"_type":"span","_key":"key-9-39dm7","text":"Nauttikaa videosta!\n\n"},{"_type":"span","_key":"key-10-25lp7","text":"https://www.youtube.com/watch?v=LHJWjgPJ61w&feature=youtu.be\n\n"},{"_type":"span","_key":"key-11-ub9ez","text":"TULOKSET","marks":["strong"]},{"_type":"span","_key":"key-12-xd4g0","text":" (punaisella hylätty nosto)\n\n"}],"markDefs":[{"_type":"link","_key":"key-13-c1e9g","href":"http://hyvoimailijat.com/Wordpress/wordpress/wp-content/uploads/2019/05/Tulokset.jpg"}]},{"_type":"image","_key":"key-15-ov3nj","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQAG9PRR2D8MBQWJSXJVE.jpg","url":"/_emdash/api/media/file/01KZ3GQAG9PRR2D8MBQWJSXJVE.jpg"},"alt":""},{"_type":"block","_key":"key-20-le16b","style":"normal","children":[{"_type":"span","_key":"key-16-hbd7s","text":"\n"},{"_type":"span","_key":"key-17-2ymws","text":"PISTETILANNE","marks":["strong"]},{"_type":"span","_key":"key-18-js2b0","text":" (naisten osalta ei muutoksia, sillä kaikki osanottajat olivat miehiä)\n\n"}],"markDefs":[{"_type":"link","_key":"key-19-xrnz4","href":"http://hyvoimailijat.com/Wordpress/wordpress/wp-content/uploads/2019/05/PISTETILANNE-1.jpg"}]},{"_type":"image","_key":"key-21-vxrzj","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQATC0RRXECBQEPHWGT6K.jpg","url":"/_emdash/api/media/file/01KZ3GQATC0RRXECBQEPHWGT6K.jpg"},"alt":""},{"_type":"block","_key":"key-25-tzf6w","style":"normal","children":[{"_type":"span","_key":"key-22-1nw5w","text":"\n"},{"_type":"span","_key":"key-23-rg3l1","text":"Teksti: Jaakko\n\n"},{"_type":"span","_key":"key-24-vjykt","text":"Video: Yusif"}]}]' WHERE id = '01KZ3GDZJECBR2EZBAYGGCQ1SV';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-6-8ww8h","style":"normal","children":[{"_type":"span","_key":"key-1-pp44u","text":"Parempi myöhään kuin ei milloinkaan vai miten se meni... Kesäkiireet ohi ja uusi kausikin on alkanut, mutta viime kauden laittaminen pakettiin on jäänyt tekemättä.\n","marks":["em"]},{"_type":"span","_key":"key-2-avfkb","text":"Kyseessä oli perinteinen voimanostokisa Otahallilla. Alkuasetelmat olivat sellaiset, että Yusif oli jo varmistanut Voimaliigan voiton, sillä miehellä oli takana nippu voittoja. Naisilla tilanne oli vastaava, sillä Sonjalla oli jo 12 pisteen johto ja hän oli naisista ainoa osanottaja tässä kauden päätöskisassa.\n\n"},{"_type":"span","_key":"key-3-m6c67","text":"Jotta julkaisua ei venytetä pidemmäksi, niin tiivistetään juttua ja poimitaan merkittävimmät asiat alle luetteloksi. Katso myös video, jonka Yusif ansiokkaasti teki. "},{"_type":"span","_key":"key-4-lo96p","text":"HUOM! ","marks":["strong"]},{"_type":"span","_key":"key-5-r928x","text":"jutun lopusta löytyvät myös kauden kokonaistulokset."}]},{"_type":"block","_key":"key-8-h1si1","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-7-4fliv","text":"Kisajärjestelyt (mm. yksi ylimääräinen tietokoneen näyttö)"}]},{"_type":"block","_key":"key-10-okilh","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-9-f7at9","text":"Jyri ja Sami vaativina tuomareina"}]},{"_type":"block","_key":"key-12-36c34","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-11-ipdax","text":"Yusifin 200 kg kyykky (lähes)"}]},{"_type":"block","_key":"key-14-91sv1","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-13-bmv6i","text":"Yusifin 150 kg penkki"}]},{"_type":"block","_key":"key-16-1eifl","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-15-77ham","text":"Maxin huomattava maastanoston parannus (250 kg)"}]},{"_type":"block","_key":"key-18-y79lz","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-17-85d0m","text":"Yusifin 600 kg yt"}]},{"_type":"block","_key":"key-20-fzp9v","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-19-dn336","text":"Kovatasoinen maastonostokisa (pl. allekirjoittanut)"}]},{"_type":"block","_key":"key-24-dnwl5","style":"normal","children":[{"_type":"span","_key":"key-21-b8c99","text":"https://youtu.be/wnpTAiL8kxY\n\n"},{"_type":"span","_key":"key-22-o2him","text":""}],"markDefs":[{"_type":"link","_key":"key-23-ptguq","href":"http://hyvoimailijat.com/Wordpress/wordpress/wp-content/uploads/2019/10/Miehet-kisatulos-5-2019.jpg"}]},{"_type":"image","_key":"key-25-4cf3s","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQDY5WQ3B9DN5TKBVQ96V.jpg","url":"/_emdash/api/media/file/01KZ3GQDY5WQ3B9DN5TKBVQ96V.jpg"},"alt":""},{"_type":"block","_key":"key-30-1jqf5","style":"normal","children":[{"_type":"span","_key":"key-26-1q7l7","text":"Miesten päätökisan tulokset."},{"_type":"span","_key":"key-27-z5kzu","text":" \n\n"},{"_type":"span","_key":"key-28-jgokb","text":""}],"markDefs":[{"_type":"link","_key":"key-29-pgiw1","href":"http://hyvoimailijat.com/Wordpress/wordpress/wp-content/uploads/2019/10/Naiset-kisatulos-5-2019.jpg"}]},{"_type":"image","_key":"key-31-o5y58","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQF39EF9GAZSTY601F8ME.jpg","url":"/_emdash/api/media/file/01KZ3GQF39EF9GAZSTY601F8ME.jpg"},"alt":""},{"_type":"block","_key":"key-35-8dbw1","style":"normal","children":[{"_type":"span","_key":"key-32-ybpck","text":"Naisten päätöskisan tulokset"},{"_type":"span","_key":"key-33-efv75","text":""}],"markDefs":[{"_type":"link","_key":"key-34-whnkj","href":"http://hyvoimailijat.com/Wordpress/wordpress/wp-content/uploads/2019/10/Yhteiskuva.jpg"}]},{"_type":"image","_key":"key-36-ahyej","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQFQEC6PRTVH5WZ8GV14C.jpg","url":"/_emdash/api/media/file/01KZ3GQFQEC6PRTVH5WZ8GV14C.jpg"},"alt":""},{"_type":"block","_key":"key-41-i1i7h","style":"normal","children":[{"_type":"span","_key":"key-37-pov9q","text":"Ylhäältä vasemmalta: Jaakko, Jyri, Valtteri, Max, Sonja, Tommi. Alhaalla Sami ja Yusif"},{"_type":"span","_key":"key-38-pjhp9","text":" \n\n"},{"_type":"span","_key":"key-39-16c2w","text":"KAUDEN LOPPUTULOKSET:\n\n"}],"markDefs":[{"_type":"link","_key":"key-40-fgpte","href":"http://hyvoimailijat.com/Wordpress/wordpress/wp-content/uploads/2019/10/Miehet-kauden-lopputulos-1.jpg"}]},{"_type":"image","_key":"key-42-ywu8e","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQH58MTWSH8PAHE32AB01.jpg","url":"/_emdash/api/media/file/01KZ3GQH58MTWSH8PAHE32AB01.jpg"},"alt":""},{"_type":"image","_key":"key-49-s9zr6","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQFDAMJ509NM18927K2EW.jpg","url":"/_emdash/api/media/file/01KZ3GQFDAMJ509NM18927K2EW.jpg"},"alt":""},{"_type":"block","_key":"key-55-fpz38","style":"normal","children":[{"_type":"span","_key":"key-50-nwy16","text":"Tällä kaudella oli vain kaksi naista. Sonja osallistui ainoana vaadituun määrään (3) kisoja."},{"_type":"span","_key":"key-51-k567x","text":" \n\n"},{"_type":"span","_key":"key-52-fligc","text":"Teksti: Jaakko\n\n"},{"_type":"span","_key":"key-53-h52h4","text":"Video: Yusif\n\n"},{"_type":"span","_key":"key-54-5uiwu","text":" "}]}]' WHERE id = '01KZ3GE1RN2XH3TJJR5MASD3P2';
UPDATE "ec_posts" SET "content" = '[{"_type":"image","_key":"key-4-ntmrp","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQG670M7SCJ6WAYHWW2JM.jpg","url":"/_emdash/api/media/file/01KZ3GQG670M7SCJ6WAYHWW2JM.jpg"},"alt":""},{"_type":"block","_key":"key-12-s09ke","style":"normal","children":[{"_type":"span","_key":"key-5-asbp5","text":"Kuva: Aulis Lindfors"},{"_type":"span","_key":"key-6-0w87y","text":"Välillä voisi kuvitella Juhan olevan myös erittäin kovassa aerobisessa kunnossa, sillä matkaaminen kisasta toiseen vaatii jo jonkinlaista kiirehtimistå.. Ehkä mies onkin? ;)\n\n"},{"_type":"span","_key":"key-7-aom5f","text":"Kyseessä oli siis Juhan 157. kisa. Tällä kertaa kotimaassa ja Suomen Voimapunnerrus ry:n järjestämä mittelö, jossa Juhan ylivoimainen kunto mahdollisti SE-raudan kokeilun. Luen alta miehen mietteet ja tarkista videolta miten tiukkoja (tai helppoja) nostot todellisuudessa olivat.\n\n"},{"_type":"span","_key":"key-8-j6ovg","text":"Viime lauantaina Lopen Voima ja kuntotiimi järjesti maksimivoimapunnerruskisat. Samalla SVRY juhlisti 10. toimintavuottaan ADT:n alaisena kisaorganisaattorina.Kisat alkoi mm. maamme laululla!\n","marks":["em"]},{"_type":"span","_key":"key-9-ful6g","text":"Allekirjoittanut osallistui kisaan sarjassa alle 93kg M60 ikäluokkaan.\n","marks":["em"]},{"_type":"span","_key":"key-10-o7jvp","text":"https://www.youtube.com/watch?v=tforAuHD6Zg\n\n"},{"_type":"span","_key":"key-11-82fv3","text":" "}]},{"_type":"block","_key":"key-14-y2wog","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-13-bzepj","text":"Nosto: 145 kg : good lift (1:16:00)"}]},{"_type":"block","_key":"key-16-yuc2q","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-15-uhlei","text":"Nosto: 150 kg: good lift (1:23:45) voitto nosto"}]},{"_type":"block","_key":"key-18-8xe0y","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-17-hplxk","text":"Nosto: 155 kg: no lift (1:32:12) SE yritys"}]},{"_type":"block","_key":"key-22-8q5il","style":"normal","children":[{"_type":"span","_key":"key-19-fcydb","text":"Kisa voitto tuli toisella nostolla, sillä toiseksi tullut Arto Malava ”pummasi” 147.5 kg toisella nostolla, mutta sai sen ylös viimeisellä yrityksellä. Tämä tarjosi minulle mahdollisuuden yrittää parantaa nimissäni olevaa SE lukemaa 152.5 kg. Tanko lähti kyllä rinnasta, mutta vauhti ei riittänyt enkä saanut tankoa ojentajille ja nosto epäonnistui.\n","marks":["em"]},{"_type":"span","_key":"key-20-9wpoq","text":"Kyseessä oli allekirjoittaneen 19. suomen mestaruus. Kaikkiaan kyseessä oli 32 SM mitali. (19 kultaa, 9 hopeaa ja 4 pronssia, muita meriittejä ovat klassisen penkin MM kulta 2018 ja MM hopea 2018). Olen tänä vuonna osallistunut 8 kisaan, joita on kertynyt vuodesta 2006 alkaen 157.\n","marks":["em"]}],"markDefs":[{"_type":"link","_key":"key-21-2zl44","href":"http://hyvoimailijat.com/Wordpress/wordpress/wp-content/uploads/2019/10/Juha-Koivisto-Max-VP-SM-2019-Loppi.png"}]},{"_type":"image","_key":"key-23-ak94f","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQGNKP15437XBA4VB7102.png","url":"/_emdash/api/media/file/01KZ3GQGNKP15437XBA4VB7102.png"},"alt":""},{"_type":"block","_key":"key-27-f4js6","style":"normal","children":[{"_type":"span","_key":"key-24-dm7a6","text":"\n"},{"_type":"span","_key":"key-25-2bj3c","text":"Teksti: Jaakko ja Juha\n\n"},{"_type":"span","_key":"key-26-bgw6b","text":"Video: VoimaStream"}]}]' WHERE id = '01KZ3GE3VBJ22K4PHV1VPKSD1Y';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-2-w50ku","style":"normal","children":[{"_type":"span","_key":"key-1-dp6q9","text":"Kauden 2019 - 2020 ensimmäinen kisa oli nimeltään Otevoimakolmio, vaikkakin yhdessä lajissa ei niinkään mitattu otevoimaa vaan muuta \"staattista kestävyyttä\". Alkuperäinen kisasuunnitelma sisälsi lajit"}]},{"_type":"block","_key":"key-4-wbznz","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-3-rbpaj","text":"Myötäotemaastanosto (ei sormilukkoa)"}]},{"_type":"block","_key":"key-6-ayg6w","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-5-e8is2","text":"Lekan nosto vaakatasossa mahdollisimman kaukaa lyömäpäästä"}]},{"_type":"block","_key":"key-8-mytcw","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-7-coxea","text":"Krusifiksi"}]},{"_type":"block","_key":"key-14-ipgtc","style":"normal","children":[{"_type":"span","_key":"key-9-y6cip","text":"Osa kannustin-/tuomarijoukoista ei kuitenkaan päässyt paikalle - ja siksi ei lekakaan. "},{"_type":"span","_key":"key-10-l3t45","text":"Näin ollen laji 2 korvattiin vanhan kunnon levypainojen pidolla (sormien välissä).\n","marks":["strong"]},{"_type":"span","_key":"key-11-zwnjn","text":"Osallistujat näet ao. kuvasta. Olafin \"ilmottautuminen\" jäi viime hetkeen, mutta hänet hyväksyttiin yksimielisesti mukaan vaikka punnitukseen ei päässytkään (HUOM! ei tasatuloksia, joten painoilla ei väliä) ;)\n\n"},{"_type":"span","_key":"key-12-srmeu","text":""}],"markDefs":[{"_type":"link","_key":"key-13-jk3x7","href":"http://hyvoimailijat.com/Wordpress/wordpress/wp-content/uploads/2019/10/Ryhmäkuva-otevoima.jpg"}]},{"_type":"image","_key":"key-15-3fnoe","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQJAMHE97DKKGF63T4N1R.jpg","url":"/_emdash/api/media/file/01KZ3GQJAMHE97DKKGF63T4N1R.jpg"},"alt":""},{"_type":"block","_key":"key-21-9ib22","style":"normal","children":[{"_type":"span","_key":"key-16-6rj0b","text":"Ylhäällä vasemmalta (d =debyytti): Aki (d) , Mathilda (d), Reijo (päätuomari), Olaf, Tommi, Ida. Alla vasemmalta: Tuukka, Jaakko, Yusif, Yusifin pohkeet."},{"_type":"span","_key":"key-17-c8u90","text":"Myötäotemaastanosto\n","marks":["strong"]},{"_type":"span","_key":"key-18-qz43r","text":"Legenda kertoo, että ainakin yksi kovimmista (lue: kovin) myötäotevetäjä ei päässyt paikalle, joka tarkoitti muille ilmaisia pisteitä. Nostoissa käytettiin IPF-maastanostosääntöjä eli \"down!\"-komennon jälkeen painot oli saatettava alas. Loppuojennuksissa kuitenkin epäselvyydet tulkittiin nostajien eduksi. Absoluuttinen tulos ratkaisi tarkoittaen että IPF- tai WILKS-kertoimia ei käytetty lopputuloksissa. Tasatuloksissa kuitenkin kevyempi nostaja voittaa. Naiset nostivat 15 kilon tangolla ja miehillä oli normaali 20 kilon tanko. Laakerointi oli molemmissa huippuluokkaa.\n\n"},{"_type":"span","_key":"key-19-ccp5l","text":"Miehillä tulokset vaihtelivat 140,0 - 167,5 kilon ja naisilla 100 - 120 kilon välillä. Tosin, jos naisilla olisi ollut vielä neljännet yritykset, olisivat painot todennäköisesti vaihdelleet 110 - 130 välillä. Alla tulokset:\n\n"}],"markDefs":[{"_type":"link","_key":"key-20-bvqby","href":"http://hyvoimailijat.com/Wordpress/wordpress/wp-content/uploads/2019/10/myotaote-tulos.jpg"}]},{"_type":"image","_key":"key-22-bhu9o","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQJNDV31Z559XW17T9HVC.jpg","url":"/_emdash/api/media/file/01KZ3GQJNDV31Z559XW17T9HVC.jpg"},"alt":""},{"_type":"block","_key":"key-27-yc80s","style":"normal","children":[{"_type":"span","_key":"key-23-jhqgv","text":"\n"},{"_type":"span","_key":"key-24-hzduz","text":"Levypainojen pito\n","marks":["strong"]},{"_type":"span","_key":"key-25-cgc0p","text":"Koska kisa oli Kluuvissa, ei Eleikon tai Leokon rautakiekkoja päästy hypistelemään, vaan tyydyttiin Gymlecoon(?) Lajissa siis miehet pitivät molemmissa käsissä kahta 10 kilon kiekkoa (eli yht. 40 kg) ja naiset yhtä 15 kilon kiekkoa (eli yht. 30 kg) mahdollisimman kauan. Gymlecon kiekoissa oli erikoisuutena erinäiset lovet, joihin saattoi saada kätevästi sormensa. Tämä saattoi hyödyttää ainakin osaa kilpailijoista. Tulokset alla:\n\n"}],"markDefs":[{"_type":"link","_key":"key-26-q11qc","href":"http://hyvoimailijat.com/Wordpress/wordpress/wp-content/uploads/2019/10/levypaino-pito.jpg"}]},{"_type":"image","_key":"key-28-0op53","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQK0XEAW3DMK9M6VFTQV5.jpg","url":"/_emdash/api/media/file/01KZ3GQK0XEAW3DMK9M6VFTQV5.jpg"},"alt":""},{"_type":"image","_key":"key-33-lahg8","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQMAD7W7H5JFSEGTACV0R.jpg","url":"/_emdash/api/media/file/01KZ3GQMAD7W7H5JFSEGTACV0R.jpg"},"alt":""},{"_type":"block","_key":"key-39-n3jsh","style":"normal","children":[{"_type":"span","_key":"key-34-6up08","text":"Käytetyt levypainot (10 ja 15 kg)"},{"_type":"span","_key":"key-35-7h9lh","text":" \n\n"},{"_type":"span","_key":"key-36-e0toj","text":"Krusifiksi\n","marks":["strong"]},{"_type":"span","_key":"key-37-nlltf","text":"Koska HYV on täynnä nöyriä kisaajia ja kansainvälisissä voimamieskisoissa krusifiksin painot ovat 16 kiloa, päädyttiin valitsemaan miehille 7 kilon ja naisille 5 kilon käsipainot. Lopputuloksena oli erittäin hapokasta tahkoamista (ks. tulokset alla).\n\n"}],"markDefs":[{"_type":"link","_key":"key-38-yx1mf","href":"http://hyvoimailijat.com/Wordpress/wordpress/wp-content/uploads/2019/10/krusifiksi-tulos.jpg"}]},{"_type":"image","_key":"key-40-ji15r","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQKBJGBJQ9CCVDF80M2K3.jpg","url":"/_emdash/api/media/file/01KZ3GQKBJGBJQ9CCVDF80M2K3.jpg"},"alt":""},{"_type":"block","_key":"key-46-hjz10","style":"normal","children":[{"_type":"span","_key":"key-41-vg0yi","text":"\n"},{"_type":"span","_key":"key-42-8qwfw","text":" \n\n"},{"_type":"span","_key":"key-43-awhi6","text":"Sitten Leo tuli viihdyttämään ja bodattiin ja mentiin saunomaan ja syömään. Sitten menimme kotiin.\n\n"},{"_type":"span","_key":"key-44-ib8p2","text":"Lopputulokset, jotka myös samalla näyttävät kauden tilanteen:\n","marks":["strong"]}],"markDefs":[{"_type":"link","_key":"key-45-uiz87","href":"http://hyvoimailijat.com/Wordpress/wordpress/wp-content/uploads/2019/10/Lopputulos.jpg"}]},{"_type":"image","_key":"key-47-m6p88","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQM01G1JPQ7006YYSDV20.jpg","url":"/_emdash/api/media/file/01KZ3GQM01G1JPQ7006YYSDV20.jpg"},"alt":""},{"_type":"block","_key":"key-52-kjrdc","style":"normal","children":[{"_type":"span","_key":"key-48-ylran","text":"\n"},{"_type":"span","_key":"key-49-2pcqt","text":" \n\n"},{"_type":"span","_key":"key-50-llckw","text":"Teksti: Jaakko\n\n"},{"_type":"span","_key":"key-51-8ti7d","text":"Kuva: Simo"}]}]' WHERE id = '01KZ3GE4VQZF8MJF67AT2SVG5R';
UPDATE "ec_posts" SET "content" = '[{"_type":"image","_key":"key-4-kyv8a","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQP8XS62X1QSDDAD3T96Q.jpg","url":"/_emdash/api/media/file/01KZ3GQP8XS62X1QSDDAD3T96Q.jpg"},"alt":""},{"_type":"block","_key":"key-10-3iyv7","style":"normal","children":[{"_type":"span","_key":"key-5-47zre","text":"Hyviä hommia"},{"_type":"span","_key":"key-6-04qd3","text":"Hallitus on viime vuosina ollut entistä luovempi kisaohjelmien suhteen ja tällä kertaa uutena tuttavuutena tuli kisa nimeltään Pull and Pull. Lajeja siis kaksi: rinnalleveto (ykkösmaksimi) sekä hyljesoutu (toistomaksimi).\n\n"},{"_type":"span","_key":"key-7-smyze","text":"Paikalla oli runsaasti tuttuja kasvoja, mutta joukossa oli myös uusia kisaajia, jotka tekivät debyyttinsä Pull & pull -kisassa.\n\n"},{"_type":"span","_key":"key-8-x6zyf","text":""}],"markDefs":[{"_type":"link","_key":"key-9-5o4fo","href":"http://hyvoimailijat.com/Wordpress/wordpress/wp-content/uploads/2019/10/ryhmäkuva-2_pull-and-pull-nettiin.jpg"}]},{"_type":"image","_key":"key-11-f9yg9","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQMVSDFVXHFN6SH63P67K.jpg","url":"/_emdash/api/media/file/01KZ3GQMVSDFVXHFN6SH63P67K.jpg"},"alt":""},{"_type":"block","_key":"key-29-odke1","style":"normal","children":[{"_type":"span","_key":"key-12-8w413","text":"Ylhäällä vasemmalta (d =debyytti): Olaf, Max, Valtteri (d), Mathilda, Ida (tuomari), Hector (d). Alhaalla vasemmalta: Jaakko ja Tuukka."},{"_type":"span","_key":"key-13-y2a8x","text":" \n\n"},{"_type":"span","_key":"key-14-mhqox","text":"Rinnalleveto\n","marks":["strong"]},{"_type":"span","_key":"key-15-gf2ke","text":"Vaikkakin kisalajeista tiedotettiin hyvissä ajoin, oli tekniikka ainakin miesosallistujilla hiukan hakusessa. Yksi kovimmista hauiskääntäjäkonkareista ei osallistunut (syy: mysteeri), mikä toisaalta antoi muille kilpailijoille mahdollisuuden kerätä vihdoin kaipaamiansa pisteitä. Lajissa ei huomioitu nostajien omaa painoa muutoin kuin tasatilanteessa kevyemmän eduksi. Esimerkiksi Max painoi Olafia 100 g vähemmän ja heidän ajauduttua tasatilanteeseen (90 kg), sai Max yhden pisteen enemmän.\n\n"},{"_type":"span","_key":"key-16-6txde","text":"Naisissa Mathilda oli ainoa osallistuja ja jos allekirjoittanut oikein muistaa, otti hän 4 tai 5 kertaa saman raudan (lähes) ylös - viimeisellä kerralla siis vasta onnistuneesti, joka tosin riitti voittoon! Ja jotta muille (lue miehille) ei aiheuteta enempää mielipahaa, ei kerrota kuinka tämä tulos on verrattuna miesten tuloksiin.\n\n"},{"_type":"span","_key":"key-17-21ecj","text":"Lajivoitosta miesten osalta tiukkaa kamppailua kävivät Jaakko ja Valtteri. Jaakon viimeinen paino 105 kg tuli suht mukavasti ylös ja näin paineet Valtterille lisääntyivät hänen siirtyessään nostolavalle nykimään 110 kiloa ylös. Mutta kuitenkin, harmittavasti(!!) Valtterin yritys kimmottaa paino katon kautta rinnalle päättyi huonosti ja tuloksena oli hylätty tulos "},{"_type":"span","_key":"key-18-ysnok","text":"(TULOKSET JUTUN LOPUSSA)\n","marks":["strong"]},{"_type":"span","_key":"key-19-litrf","text":"Tällä kertaa emme kiitä Yusifia editoinnista vaan nautimme raa''asta materiaalista!\n\n"},{"_type":"span","_key":"key-20-8qd70","text":"Viimeinen kierros rivessä on toisessa pätkässä.\n\n"},{"_type":"span","_key":"key-21-v10pv","text":"https://www.youtube.com/watch?v=XGnvbLX1Xio&feature=youtu.be\n\n"},{"_type":"span","_key":"key-22-0rsfr","text":" \n\n"},{"_type":"span","_key":"key-23-oc7tj","text":"https://www.youtube.com/watch?v=3EEWswiBeVE&feature=youtu.be\n\n"},{"_type":"span","_key":"key-24-ek5fi","text":"Hyljesoutu\n","marks":["strong"]},{"_type":"span","_key":"key-25-1gyz5","text":"Hyljesoutu oli toistokisa, jossa kisapaino riippui kisaajan iästä, pituudesta ja painosta. Hyljesoudussa maattiin vatsallaan penkillä ja vedettiin tanko ylös kohti rintaa/vatsan seutua. Hyväksyttyyn toistoon riitti nostaessa tangon kolahtaminen penkin metalliin ja laskiessa painojen osuessa maahan. Erot kisaajien välillä olivat pieniä. Esimerkiksi hyljesoudussa kolmen parhaan toistotulos oli 29, 28 ja 27. Maaginen 30 toistoa ei mennyt rikki tälläkään kertaa (viimeksi hyljesoutu oli lajina barbell challengessa, jolloin paras tulos oli 28 toistoa).\n\n"},{"_type":"span","_key":"key-26-wjhlt","text":"Kauden toisen kisan jälkeen Jaakko ja Mathilda ovat kärkipaikoilla.\n\n"},{"_type":"span","_key":"key-27-ggt8m","text":"https://www.youtube.com/watch?v=jKmikhlTmqc&feature=youtu.be\n\n"}],"markDefs":[{"_type":"link","_key":"key-28-mvm7p","href":"http://hyvoimailijat.com/Wordpress/wordpress/wp-content/uploads/2019/10/Lopputulokset-Pull-and-pull.jpg"}]},{"_type":"image","_key":"key-30-1ri08","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQN857HXPMPVEF0C2Q5EY.jpg","url":"/_emdash/api/media/file/01KZ3GQN857HXPMPVEF0C2Q5EY.jpg"},"alt":""},{"_type":"block","_key":"key-36-2uef6","style":"normal","children":[{"_type":"span","_key":"key-31-qxesl","text":"\n"},{"_type":"span","_key":"key-32-lps2z","text":" \n\n"},{"_type":"span","_key":"key-33-y1vog","text":"KAUDEN TILANNE\n","marks":["strong"]},{"_type":"span","_key":"key-34-k6m5n","text":"MIEHET\n"}],"markDefs":[{"_type":"link","_key":"key-35-wh82e","href":"http://hyvoimailijat.com/Wordpress/wordpress/wp-content/uploads/2019/10/Pistetilanne-10-2019.jpg"}]},{"_type":"image","_key":"key-37-s919o","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQNJCA14FMMC64VVHCFT9.jpg","url":"/_emdash/api/media/file/01KZ3GQNJCA14FMMC64VVHCFT9.jpg"},"alt":""},{"_type":"block","_key":"key-41-jgxw2","style":"normal","children":[{"_type":"span","_key":"key-38-7jvbz","text":"\n"},{"_type":"span","_key":"key-39-p3vy2","text":"NAISET\n"}],"markDefs":[{"_type":"link","_key":"key-40-bw8j2","href":"http://hyvoimailijat.com/Wordpress/wordpress/wp-content/uploads/2019/10/Pistetilanne-10-2019_naiset.jpg"}]},{"_type":"image","_key":"key-42-x6m1i","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQNZV21QMPHW4V5SCA3TH.jpg","url":"/_emdash/api/media/file/01KZ3GQNZV21QMPHW4V5SCA3TH.jpg"},"alt":""},{"_type":"block","_key":"key-48-iqdew","style":"normal","children":[{"_type":"span","_key":"key-43-auwnq","text":"\n"},{"_type":"span","_key":"key-44-vxakn","text":" \n\n"},{"_type":"span","_key":"key-45-e542z","text":"Teksti: Jaakko\n\n"},{"_type":"span","_key":"key-46-1inr9","text":"Video: Tuukka\n\n"},{"_type":"span","_key":"key-47-ork0f","text":"Kuva: Timo"}]}]' WHERE id = '01KZ3GE5ZPN847W18C536703NE';
UPDATE "ec_posts" SET "content" = '[{"_type":"image","_key":"key-4-7datf","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQB5SWVB0WFJQ1MYF6TEB.jpg","url":"/_emdash/api/media/file/01KZ3GQB5SWVB0WFJQ1MYF6TEB.jpg"},"alt":""},{"_type":"block","_key":"key-14-q8be5","style":"normal","children":[{"_type":"span","_key":"key-5-aod01","text":"From the left: Simo, Yusif, Leo, Eero and Jaakko"},{"_type":"span","_key":"key-6-vnkuw","text":"The title is a bit misleading, because back measurements are not part of Voimaliiga. A competition in that direction in the works however... ;)\n\n"},{"_type":"span","_key":"key-7-jzjpo","text":"Now, to the topic: in April we had the 2018-2019 season''s second to last competition. Exercise of choice was chinups (max weight and reps) and the venue was Unisport''s Meilahti gym.\n\n"},{"_type":"span","_key":"key-8-d8nhq","text":"As per HYV tradition, there was a lot of smack talk and flexing before the competition. We saw some insane tactics in play which lead to our first-comer (in chinups) Simo to win the max weight competition, and Jaakko won the rep competition four years in a row now. Competition level was high, but unfortunately last year''s strongest chin-uppers did not participate. Maybe next year we''ll have a mega showdown? 😉\n\n"},{"_type":"span","_key":"key-9-b6o6j","text":"Enjoy the video!\n\n"},{"_type":"span","_key":"key-10-z2ax4","text":"https://www.youtube.com/watch?v=LHJWjgPJ61w&feature=youtu.be\n\n"},{"_type":"span","_key":"key-11-e2dji","text":"Results","marks":["strong"]},{"_type":"span","_key":"key-12-ggceb","text":" (red means failed lift)\n\n"}],"markDefs":[{"_type":"link","_key":"key-13-i0l31","href":"http://hyvoimailijat.com/Wordpress/wordpress/wp-content/uploads/2019/05/Tulokset.jpg"}]},{"_type":"image","_key":"key-15-6n8y9","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQAG9PRR2D8MBQWJSXJVE.jpg","url":"/_emdash/api/media/file/01KZ3GQAG9PRR2D8MBQWJSXJVE.jpg"},"alt":""},{"_type":"block","_key":"key-19-94ldo","style":"normal","children":[{"_type":"span","_key":"key-16-p0zh1","text":"\n"},{"_type":"span","_key":"key-17-3du9u","text":"Voimaliiga points\n","marks":["strong"]}],"markDefs":[{"_type":"link","_key":"key-18-li7qu","href":"http://hyvoimailijat.com/Wordpress/wordpress/wp-content/uploads/2019/05/PISTETILANNE-1.jpg"}]},{"_type":"image","_key":"key-20-b89r8","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQATC0RRXECBQEPHWGT6K.jpg","url":"/_emdash/api/media/file/01KZ3GQATC0RRXECBQEPHWGT6K.jpg"},"alt":""},{"_type":"block","_key":"key-25-15nfl","style":"normal","children":[{"_type":"span","_key":"key-21-pgt8m","text":"\n"},{"_type":"span","_key":"key-22-ur9fl","text":"Translated by: Yusif\n\n"},{"_type":"span","_key":"key-23-prd1u","text":"Original text: Jaakko\n\n"},{"_type":"span","_key":"key-24-c7zks","text":"Video: Yusif"}]}]' WHERE id = '01KZ3GE6YX470K981P2GRSGE9M';
UPDATE "ec_posts" SET "content" = '[{"_type":"image","_key":"key-4-e2j7k","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQA45YSJ55XSHYEHADJ78.jpg","url":"/_emdash/api/media/file/01KZ3GQA45YSJ55XSHYEHADJ78.jpg"},"alt":""},{"_type":"block","_key":"key-14-1yq3g","style":"normal","children":[{"_type":"span","_key":"key-5-x0tw4","text":"From the top left: Jaakko, Olaf, Tommi, Sonja, Valtteri, Max, Ville, Pasi. Alhaalla Yusif and Sami."},{"_type":"span","_key":"key-6-ou2w9","text":"In order for us to not lose the touch on the deadlift (there''s half a year gap between two powerlifting competitions), HYV organized a Push&Pull competition, where the we show off our benchpress and deadlift one rep maxes.\n\n"},{"_type":"span","_key":"key-7-po89m","text":"This time around we had 8 participants, and everybody had prior competition experience.\n\n"},{"_type":"span","_key":"key-8-n82ls","text":"Some notable lifts from the competitons are Olaf''s 160 kg bench and Yusif''s "},{"_type":"span","_key":"key-9-7emp9","text":"almost","marks":["em"]},{"_type":"span","_key":"key-10-1gjkz","text":" raw (no belt but sumo) 245 kg deadlift attempts. Check out the video to find out if they got it! ;)\n\n"},{"_type":"span","_key":"key-11-aly4u","text":"https://www.youtube.com/watch?v=hVWmCUIB_NI\n\n"},{"_type":"span","_key":"key-12-wcfqv","text":"Results:","marks":["strong"]}],"markDefs":[{"_type":"link","_key":"key-13-uf7x2","href":"http://hyvoimailijat.com/Wordpress/wordpress/wp-content/uploads/2019/05/Tulokset_PushPull-3-2019.jpg"}]},{"_type":"image","_key":"key-15-duqe4","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQ9554XENM1FKBPDQQHHJ.jpg","url":"/_emdash/api/media/file/01KZ3GQ9554XENM1FKBPDQQHHJ.jpg"},"alt":""},{"_type":"block","_key":"key-20-37dn7","style":"normal","children":[{"_type":"span","_key":"key-16-vd4q8","text":"\n"},{"_type":"span","_key":"key-17-z3j31","text":"Voimaliiga points\n\n","marks":["strong"]},{"_type":"span","_key":"key-18-e1q8q","text":"Gents\n\n"}],"markDefs":[{"_type":"link","_key":"key-19-z3mi0","href":"http://hyvoimailijat.com/Wordpress/wordpress/wp-content/uploads/2019/05/PISTETILANNE_miehet.jpg"}]},{"_type":"image","_key":"key-21-hd3it","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQ9ECE7C24KKHNBAK7AZ8.jpg","url":"/_emdash/api/media/file/01KZ3GQ9ECE7C24KKHNBAK7AZ8.jpg"},"alt":""},{"_type":"block","_key":"key-25-7as7h","style":"normal","children":[{"_type":"span","_key":"key-22-8y9zi","text":"\n"},{"_type":"span","_key":"key-23-ant22","text":"Ladies\n\n"}],"markDefs":[{"_type":"link","_key":"key-24-9jqk3","href":"http://hyvoimailijat.com/Wordpress/wordpress/wp-content/uploads/2019/05/PISTETILANNE_naiset.jpg"}]},{"_type":"image","_key":"key-26-lfre0","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQ9QQ0H2DYZ7573XMFXX2.jpg","url":"/_emdash/api/media/file/01KZ3GQ9QQ0H2DYZ7573XMFXX2.jpg"},"alt":""},{"_type":"block","_key":"key-31-0ktgd","style":"normal","children":[{"_type":"span","_key":"key-27-rkuk6","text":"\n"},{"_type":"span","_key":"key-28-q2qyh","text":"Translated by: Yusif\n\n"},{"_type":"span","_key":"key-29-g2fik","text":"Original text: Jaakko\n\n"},{"_type":"span","_key":"key-30-8d3dt","text":"Video: Yusif"}]}]' WHERE id = '01KZ3GE914198780VVFA4YMWFJ';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-3-t94ax","style":"normal","children":[{"_type":"span","_key":"key-1-a4nc1","text":"This is a classic HYV competition, which is held at Otahalli (Unisport''s gym in Otaniemi). Even before the competition the Voimaliiga winner was already determined, as Yusif had a bunch of wins in the bag already. Similar case was for the ladies, as Sonja had a 12 point lead coming into the competition and was the only girl taking part in the final competition.\n\n"},{"_type":"span","_key":"key-2-16ehr","text":"Don''t want to bore you anymore with the long text, so we''ll condense the results and pick out the juiciest bits for you in a bullet list."}]},{"_type":"block","_key":"key-5-6raer","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-4-nxs0p","text":"Organizational stuff (extra monitor)"}]},{"_type":"block","_key":"key-7-6ncfy","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-6-ona2h","text":"Jyri and Sami being tough judges"}]},{"_type":"block","_key":"key-9-e2oq1","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-8-2m3va","text":"Yusif''s 200 kg squat attempt"}]},{"_type":"block","_key":"key-11-7tlk8","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-10-iu3o6","text":"Yusif''s 150 kg bench attempt"}]},{"_type":"block","_key":"key-13-zlncp","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-12-9cb9i","text":"Max''s insane deadlift progress to 250 kg"}]},{"_type":"block","_key":"key-15-cphnd","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-14-9a21k","text":"Yusif''s first 600 kg powerlifting total"}]},{"_type":"block","_key":"key-17-b4f0c","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-16-zogex","text":"Some heavy-ass deadlifts"}]},{"_type":"block","_key":"key-22-0a2g9","style":"normal","children":[{"_type":"span","_key":"key-18-bvcru","text":"Also make sure to watch the video (we thank Yusif for the editing job)!\n\n"},{"_type":"span","_key":"key-19-ba9qt","text":"https://youtu.be/wnpTAiL8kxY\n\n"},{"_type":"span","_key":"key-20-rx781","text":""}],"markDefs":[{"_type":"link","_key":"key-21-9p4go","href":"http://hyvoimailijat.com/Wordpress/wordpress/wp-content/uploads/2019/10/Miehet-kisatulos-5-2019.jpg"}]},{"_type":"image","_key":"key-23-1idxb","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQDY5WQ3B9DN5TKBVQ96V.jpg","url":"/_emdash/api/media/file/01KZ3GQDY5WQ3B9DN5TKBVQ96V.jpg"},"alt":""},{"_type":"block","_key":"key-28-r5csg","style":"normal","children":[{"_type":"span","_key":"key-24-a30cx","text":"Results, men."},{"_type":"span","_key":"key-25-krlzq","text":" \n\n"},{"_type":"span","_key":"key-26-sekll","text":""}],"markDefs":[{"_type":"link","_key":"key-27-ytjk1","href":"http://hyvoimailijat.com/Wordpress/wordpress/wp-content/uploads/2019/10/Naiset-kisatulos-5-2019.jpg"}]},{"_type":"image","_key":"key-29-8n97t","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQF39EF9GAZSTY601F8ME.jpg","url":"/_emdash/api/media/file/01KZ3GQF39EF9GAZSTY601F8ME.jpg"},"alt":""},{"_type":"block","_key":"key-33-hohv2","style":"normal","children":[{"_type":"span","_key":"key-30-bj44d","text":"Results, women"},{"_type":"span","_key":"key-31-69683","text":""}],"markDefs":[{"_type":"link","_key":"key-32-fjnkl","href":"http://hyvoimailijat.com/Wordpress/wordpress/wp-content/uploads/2019/10/Yhteiskuva.jpg"}]},{"_type":"image","_key":"key-34-d8r6g","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQFQEC6PRTVH5WZ8GV14C.jpg","url":"/_emdash/api/media/file/01KZ3GQFQEC6PRTVH5WZ8GV14C.jpg"},"alt":""},{"_type":"block","_key":"key-39-qz2xs","style":"normal","children":[{"_type":"span","_key":"key-35-5upwc","text":"From top left Jaakko, Jyri, Valtteri, Max, Sonja, Tommi. Bottom row Yusif and Sami"},{"_type":"span","_key":"key-36-muqpv","text":" \n\n"},{"_type":"span","_key":"key-37-24e7o","text":"Voimaliiga final standings:\n\n"}],"markDefs":[{"_type":"link","_key":"key-38-42l5j","href":"http://hyvoimailijat.com/Wordpress/wordpress/wp-content/uploads/2019/10/Miehet-kauden-lopputulos-1.jpg"}]},{"_type":"image","_key":"key-40-u3syh","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQH58MTWSH8PAHE32AB01.jpg","url":"/_emdash/api/media/file/01KZ3GQH58MTWSH8PAHE32AB01.jpg"},"alt":""},{"_type":"image","_key":"key-44-4cl2x","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQFDAMJ509NM18927K2EW.jpg","url":"/_emdash/api/media/file/01KZ3GQFDAMJ509NM18927K2EW.jpg"},"alt":""},{"_type":"block","_key":"key-51-9t4q5","style":"normal","children":[{"_type":"span","_key":"key-45-mvfhu","text":"\n"},{"_type":"span","_key":"key-46-sv6bq","text":" \n\n"},{"_type":"span","_key":"key-47-578j1","text":"Translated by: Yusif\n\n"},{"_type":"span","_key":"key-48-mxh0m","text":"Original text: Jaakko\n\n"},{"_type":"span","_key":"key-49-s4ai6","text":"Video: Yusif\n\n"},{"_type":"span","_key":"key-50-kfcuz","text":" "}]}]' WHERE id = '01KZ3GEA00YNT21ZPJYM0DGP88';
COMMIT;

BEGIN TRANSACTION;
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-10-tfmdv","style":"normal","children":[{"_type":"span","_key":"key-1-phj90","text":"Jo vuosia tapana ollut joulukuun voimanostokisa pidettiin kovan väännön jälkeen Otahallilla. Pienen informaatiokatkon jälkeen kaikki kisaajat olivat kuitenkin enemmän tai vähemmän ajoissa ja, mikä tärkeintä, oikeassa paikassa.\n\n"},{"_type":"span","_key":"key-2-muwpb","text":"Ennen kisaa tuli valitettavan monta peruutusta. Aivan kuten edellisessä jutussa mainitsin Ivanin sairastumisesta, ei täyttä parantumista myöskään viikkoa myöhempään kisaan saatu. Ivanin lisäksi myös Axu ilmoitti kisa-aamuna flunssasta. Näin ollen emme päässeet näkemään ehkä HYV:n suurimpia mavekorotuksia. Pari muuta kisaajaa kokivat vastaavanlaisia oloja mutta eri syistä: Yusif kikkaillessaan painonsa kanssa ja kokeillessaan muokattua T-nationin \"shredded in 6 days\" -menetelmää tai allekirjoittanut lyhyiden uniensa vuoksi.\n\n"},{"_type":"span","_key":"key-3-u0k8z","text":"Tänä vuonna saimme miehiin uuden kisaajan, Jonnen, jonka taso oli tietenkin jo ennen kisaa tarkkailtu Youtubesta. Filmien perusteella saimme mukaan yhden kärkisijoista kamppailevan nostajan. Naisissa uusia kisaajia oli kaksi, Ida ja Oili, jotka haastoivat jo kisakokemusta kerryttäneen Veeran.\n\n"},{"_type":"span","_key":"key-4-xhdju","text":"Viime kisoista oppineena saimme mukaan kolme tuomaria: Sami, Reijo ja Jyri. Näin ollen huutoäänestyksiä ei jouduttu pitämään.\n\n"},{"_type":"span","_key":"key-5-lm8yn","text":"Jalkakyykky\n","marks":["strong"]},{"_type":"span","_key":"key-6-8vlpp","text":"Kyykky lähti kaikilla rutiininomaisesti käyntiin. Valitettavasti \"katsojat\" tulivat myöhässä ja kisaajat toimivat nostojensa lisäksi lastaajina. Kahdeksan kisaajan seurue oli onneksi sopivan kokoinen tällaiseen säätöön ja kisa ei venynyt totuttua pidemmäksi.\n\n"},{"_type":"span","_key":"key-7-g9a0x","text":"Miesten kovimmista kyykyistä vastasivat Jonne ja Tuukka. Molemmat kyykähtivät selkeästi syvän 210 kg (ks. kuva alla). Naisissa taas kovimman raudan, 110 kg, taisteli ylös Ida. Jutun lopusta löytyvät kisavideot, joten löydätte kaikkien kyykky- ja penkkisuoritukset sieltä. Kun katsotte kyykkyä, niin huomioikaa kuvakulma: videolla lähes kaikki kyykyt näyttävät riittävän syviltä, mutta osa niistä silti hylättiin. IPF-tuomaroinnissa on totuttava tiukkoihin tuomioihin.\n\n"},{"_type":"span","_key":"key-8-u6xar","text":""}],"markDefs":[{"_type":"link","_key":"key-9-lqztq","href":"http://hyvoimailijat.com/Wordpress/wordpress/wp-content/uploads/2017/12/Tuukka-kyykky.jpg"}]},{"_type":"image","_key":"key-11-7pque","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GPN705PFAF8BQKCVEW0CD.jpg","url":"/_emdash/api/media/file/01KZ3GPN705PFAF8BQKCVEW0CD.jpg"},"alt":"Tuukan huippusyvä 210 kg. Suora kulma lisätty jälkikäteen. Kuvauskulman vuoksi ei anna kuitenkaan todellista kuvaa syvyydestä."},{"_type":"block","_key":"key-15-9em8p","style":"normal","children":[{"_type":"span","_key":"key-12-fvc3a","text":"Tuukan huippusyvä 210 kg. Suora kulma lisätty jälkikäteen. Kuvauskulman vuoksi ei anna kuitenkaan todellista kuvaa syvyydestä."},{"_type":"span","_key":"key-13-vdbuf","text":""}],"markDefs":[{"_type":"link","_key":"key-14-e0d4y","href":"http://hyvoimailijat.com/Wordpress/wordpress/wp-content/uploads/2017/12/Veera-ja-Ida.jpg"}]},{"_type":"image","_key":"key-16-atc7w","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GPNJBHFDPE4356MMVEX7M.jpg","url":"/_emdash/api/media/file/01KZ3GPNJBHFDPE4356MMVEX7M.jpg"},"alt":"Nostojen välissä psyykkailtiin kukin omalla tavallaan. Veera ja Ida saivat hymyilystä huolimatta kovia suorituksia aikaiseksi. Kuva: Anniliina Lassila"},{"_type":"block","_key":"key-33-0zaeo","style":"normal","children":[{"_type":"span","_key":"key-17-nqlap","text":"Nostojen välissä psyykkailtiin kukin omalla tavallaan. Veera ja Ida saivat hymyilystä huolimatta kovia suorituksia aikaiseksi. Kuva: Anniliina Lassila"},{"_type":"span","_key":"key-18-e3rsu","text":"Penkkipunnerrus\n","marks":["strong"]},{"_type":"span","_key":"key-19-bbzrh","text":"Ennen penkkipunnerruksen alkua katsoja-toimitsijoita oli päässyt paikalle jo jonkin verran. Kluuvin sanansaattaja Leo vastasi viihdyttämisestä hämmentäessään kilpailijoita omalla tavallaan. Hyvä niitä kisaajien henkistä puoltakin on testattava. ;)\n\n"},{"_type":"span","_key":"key-20-4xkqu","text":"Päätuomarin vaihduttua toukokuun kisasta, ottivat kisaajat vallan valitessaan kisapenkkiä ja -tankoa. Näin ollen lopputulemana oli \"epävirallinen\" tanko, josta kuitenkin tehtiin virallinen vain tarkkailemalla oteleveyksiä normaalia tarkemmin. Ehkä se selittää erityisen kovat tulokset...\n\n"},{"_type":"span","_key":"key-21-241j3","text":"Naisissa energiaa riitti myös neljänsiin nostoihin: Veera ja Ida halusivat ottaa harmittavasti epäonnistuneet kolmannet nostonsa uusiksi. Molemmat onnistuivat, mutta näitä nostoja ei kuitenkaan rekisteröidä virallisiin tuloksiin vaan (vähintään) nostajien omiin mieliin, jotta ne muistetaan rikkoa sitten seuraavissa kisoissa.\n\n"},{"_type":"span","_key":"key-22-fs0gy","text":"Miehissä Ivan ilmeisesti rekrysi itselleen uhkaavan penkkaajan: Jonnen 155 kg nosto oli yksi kovimpia HYV:n voimanostokisoissa nähtyjä. Paketti pysyi tiukkana noston loppuun asti johtaen pienehköön selkäkramppiin mukavasti ennen maastanostoa...\n\n"},{"_type":"span","_key":"key-23-qg45q","text":"Maastanosto\n","marks":["strong"]},{"_type":"span","_key":"key-24-f3v9r","text":"Kisa jatkui tiukkana maastanostoon asti. Miehissä selkeä top 3 oli painojärjestykssä Yusif, Tuukka ja Jonne. Naisissa Ida oli karannut vahvan penkkinsä (ja toki kyykkynsäkin) siivittämänä hyvään johtoon. 155 kg veto näytti niin kevyeltä, että joko Push&Pull- tai toukokuun voimanostokisassa HYV:n naisten ennätystä tullaan vähintään sivuamaan (Katariina P:llä nykyinen ennätys 160 kg).\n\n"}],"markDefs":[{"_type":"link","_key":"key-32-iqxe9","href":"http://hyvoimailijat.com/Wordpress/wordpress/wp-content/uploads/2017/12/loppukuva.jpg"}]},{"_type":"htmlBlock","_key":"key-33-0zaeo-video-1","html":"<video controls preload=\"metadata\" src=\"http://hyvoimailijat.com/Wordpress/wordpress/wp-content/uploads/2017/12/WhatsApp-Video-2017-12-16-at-19.54.03.mp4\"></video>"},{"_type":"block","_key":"key-33-0zaeo","style":"normal","children":[{"_type":"span","_key":"key-26-gby6q","text":"Ida ja 155 kg, joka lähentelee HYV:n naisten ennätystä. (Sala)kuvaajana Leo\n","marks":["em"]},{"_type":"span","_key":"key-27-gqp5n","text":"Tällä kertaa suurimmat mave-raudat jäivät 240 kiloon. Kyykyn tavoin näistä vastasivat jälleen Tuukka ja Jonne ja molemmilla näytti olevan vielä potentiaalia neljänsiin nostoihin. Yusif taas hoiti hoikimpana mies-kisaajana kovimman WILKS-tuloksen ja vei kisan voiton. Vielä kuitenkin alle 400 WILKS, joten tavoiteltavaa rittää. ;)\n\n"},{"_type":"span","_key":"key-28-jw08c","text":"Ida keräsi jokaisessa laijssa voiton ja näin ollen poistui paikalta voittajana. Tulos oli sellaista tasoa, että sillä kehtaisi jo suunnata kansallisiin kisoihin. Toiseksi tuli Veera ja kolmanneksi debyyttinsä tehnyt Oili.\n\n"},{"_type":"span","_key":"key-29-h1l4r","text":"Sokerina pohjalla Villen 100 % RAW (no belt, no straps, no wraps, no mirror) mave.\n\n"},{"_type":"span","_key":"key-30-3ktms","text":"https://www.instagram.com/p/Bcx6UfQg6yM/\n\n"},{"_type":"span","_key":"key-31-z6fko","text":""}],"markDefs":[{"_type":"link","_key":"key-32-iqxe9","href":"http://hyvoimailijat.com/Wordpress/wordpress/wp-content/uploads/2017/12/loppukuva.jpg"}]},{"_type":"image","_key":"key-34-y2v2w","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GPRK9ZPJ1S97K61AANSBB.jpg","url":"/_emdash/api/media/file/01KZ3GPRK9ZPJ1S97K61AANSBB.jpg"},"alt":"Voittajan tehtävä on olla yläosattomissa ;)"},{"_type":"block","_key":"key-39-7tp2r","style":"normal","children":[{"_type":"span","_key":"key-35-m1alf","text":"Voittajan tehtävä on olla yläosattomissa ;)"},{"_type":"span","_key":"key-36-l90uc","text":" \n\n"},{"_type":"span","_key":"key-37-ngxke","text":"Tuloksia ja kauden tilanne alla.\n\n"}],"markDefs":[{"_type":"link","_key":"key-38-ggvox","href":"http://hyvoimailijat.com/Wordpress/wordpress/wp-content/uploads/2017/12/Tulokset-HYV-2017-joulu-1.jpg"}]},{"_type":"image","_key":"key-40-9ibfa","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GPQ49KPERMXWWRQ3F5S6T.jpg","url":"/_emdash/api/media/file/01KZ3GPQ49KPERMXWWRQ3F5S6T.jpg"},"alt":"Tulokset HYV 2017 joulu"},{"_type":"block","_key":"key-44-6ufwr","style":"normal","children":[{"_type":"span","_key":"key-41-3i45n","text":"\n"},{"_type":"span","_key":"key-42-d5s0u","text":"Alla lajikohtaiset tulokset\n","marks":["strong"]}],"markDefs":[{"_type":"link","_key":"key-43-z5uls","href":"http://hyvoimailijat.com/Wordpress/wordpress/wp-content/uploads/2017/12/Nostot.jpg"}]},{"_type":"image","_key":"key-45-4s16w","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GPR87JQ6X3SQRW5DZJX4J.jpg","url":"/_emdash/api/media/file/01KZ3GPR87JQ6X3SQRW5DZJX4J.jpg"},"alt":"Nostot"},{"_type":"block","_key":"key-49-1gyye","style":"normal","children":[{"_type":"span","_key":"key-46-93nan","text":"\n"},{"_type":"span","_key":"key-47-dfyw7","text":"Kauden pistetilanne\n","marks":["strong"]}],"markDefs":[{"_type":"link","_key":"key-48-qqp98","href":"http://hyvoimailijat.com/Wordpress/wordpress/wp-content/uploads/2017/12/Pistetilanne-naiset.jpg"}]},{"_type":"image","_key":"key-50-4pit9","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GPQEJH7440W3KANV3EWN6.jpg","url":"/_emdash/api/media/file/01KZ3GPQEJH7440W3KANV3EWN6.jpg"},"alt":"Pistetilanne naiset"},{"_type":"image","_key":"key-53-mr8kz","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GPQRV4EQ0T3B7H730P252.jpg","url":"/_emdash/api/media/file/01KZ3GPQRV4EQ0T3B7H730P252.jpg"},"alt":"Pistetilanne miehet"},{"_type":"block","_key":"key-63-saj2e","style":"normal","children":[{"_type":"span","_key":"key-54-e2plo","text":"\n"},{"_type":"span","_key":"key-55-c3eah","text":"Kisavideot\n","marks":["strong"]},{"_type":"span","_key":"key-56-zdk6k","text":"https://www.youtube.com/watch?v=SdK5qXcpr0o&feature=youtu.be\n\n"},{"_type":"span","_key":"key-57-dszol","text":" \n\n"},{"_type":"span","_key":"key-58-cii1b","text":"https://www.youtube.com/watch?v=NqTP3bYFMQ4&feature=youtu.be\n\n"},{"_type":"span","_key":"key-59-ahbxa","text":"Juttua päivitetty 25.12.2017 klo 20:47: Idan maastanosto ei sivunnut nykyistä HYV:n naisten ennätystä.\n","marks":["em"]},{"_type":"span","_key":"key-60-rrv9k","text":"Teksti: Jaakko\n\n"},{"_type":"span","_key":"key-61-uz4o2","text":"Kuvat: Anniliina Lassila ja Jyri\n\n"},{"_type":"span","_key":"key-62-vzy47","text":"Videot: Leo ja Yusif"}]}]' WHERE id = '01KZ3GDFYFNCZ4Z9SFHNEPZ75X';
